// Bitmap font format of the VMS fonts (include/fonts/*.h, generated by tools/vmsfont.py).
// Same idea as Adafruit GFXfont: one packed row-major bit stream per glyph, MSB first.
#pragma once
#include <stdint.h>

struct VmsGlyph {
  uint16_t off;     // first byte in the bitmap array
  uint8_t  w, h;    // glyph box
  uint8_t  adv;     // pen advance
  int8_t   xo, yo;  // box top-left relative to the pen position on the baseline
};

struct VmsFont {
  const uint8_t  *bitmap;
  const VmsGlyph *glyph;
  uint8_t first, last;
};
